(function(){
  var root=document.querySelector('[data-manga-app]');if(!root)return;
  var storage='https://firebasestorage.googleapis.com/v0/b/poketquest-3a73d.firebasestorage.app/o/japaneseLearning%2Fmanga%2Fn4%2F';
  var stories=[
    {slug:'toilets',fallback:'n4-toilets',title:'Japan’s Toilets: The System Under the Buttons',rail:'Look for what failed—and what the manga says matters more than buttons.'},
    {slug:'akihabara',fallback:'n4-akihabara',title:'Akihabara: What Never Changes',rail:'Look for why the shops gathered and what remained after the products changed.'},
    {slug:'aka-manto',fallback:'n4-aka-manto',title:'Aka Manto: Refuse the Trap',rail:'Look for what happened after YUJI chose red and which earlier warning helped him escape.'}
  ];
  var copy={readerKicker:'READ THE STORY',readerTitle:'Start with the Japanese edition.',readerHint:'Read from the upper right and follow the numbered panels.',completeTitle:'You understood all three stories.',completeCopy:'You completed the N4 manga collection, including the new Aka Manto story.',startQuestions:'Start this manga’s questions →',reread:'▣ Read the manga again',readAgain:'Read the collection again',backToCourses:'Back to courses →'};
  var questions=[
    {q:'What did YUJI realize when the power and water stopped?',c:['Machines alone cannot help everyone','Foreign toilets cannot be used','They had to leave the station','Pressing every button would help'],a:0,e:'Useful machines cannot help people when the systems beneath them stop.'},
    {q:"What is the true power of Japan's toilets in the manga?",c:['Many buttons','A warm seat','A system that does not leave people stranded','A privacy sound'],a:2,e:'Their strength is accessible, understandable, maintained infrastructure.'},
    {q:'Why did radio shops gather in Akihabara after the war?',c:['Street shops moved close to the station','Anime had become popular','A large shrine was built','The trains stopped running'],a:0,e:'Street vendors were moved to covered spaces near and beneath the railway, creating a concentrated radio-parts market.'},
    {q:'What stayed the same in Akihabara even when the products changed?',c:['Its wide roads','Its old radios','People gathering to treasure and deeply understand what they love','The names of every shop'],a:2,e:'The products changed, but the culture of deep specialist interest remained.'},
    {q:"What happened after YUJI chose red when Aka Manto asked 'red or blue'?",c:['Red cloth pinned him in place','Blue water flooded the room','The exit opened immediately','Aka Manto became his friend'],a:0,e:'Red cloth wrapped around YUJI and stopped him from moving.'},
    {q:"How did YUJI escape Aka Manto's forced choice?",c:['He changed his answer to blue','He refused to choose either red or blue','He shouted for help','He gave Aka Manto his phone'],a:1,e:"Remembering the viewer's warning, YUJI rejected the two choices instead of choosing another color."}
  ];
  Object.keys(copy).forEach(function(key){var node=root.querySelector('[data-ui="'+key+'"]');if(node)node.textContent=copy[key];});
  var reader=root.querySelector('[data-reader]'),quiz=root.querySelector('[data-quiz]'),complete=root.querySelector('[data-complete]'),image=root.querySelector('[data-manga-image]'),frame=root.querySelector('.manga-frame'),status=root.querySelector('[data-image-status]'),progress=root.querySelector('[data-progress-bar]'),stateKey='japaneseLearning.manga.n4_manga.nextQuestion.v1';
  var saved=Math.max(0,Math.min(questions.length,Number(localStorage.getItem(stateKey))||0));
  var params=new URLSearchParams(location.search),directStory=params.get('story');
  var index=directStory==='aka-manto'?4:Math.min(questions.length-1,saved),locked=false;
  function storyIndex(){return Math.min(stories.length-1,Math.floor(index/2));}
  function save(value){localStorage.setItem(stateKey,String(value));window.dispatchEvent(new CustomEvent('manga-progress',{detail:{courseId:'n4_manga',completedSteps:value,totalSteps:questions.length,progressPercent:value*100/questions.length}}));}
  function updateStoryCopy(){var story=stories[storyIndex()],title=root.querySelector('[data-ui="lessonTitle"]'),rail=root.querySelector('[data-ui="quizRail"]');if(title)title.textContent=story.title;if(rail)rail.textContent=story.rail;}
  function loadImage(lang){var story=stories[storyIndex()],firebase=storage+story.slug+'%2Fv1%2F';frame.classList.remove('loaded');status.textContent='Loading manga…';image.dataset.fallback='0';image.onload=function(){frame.classList.add('loaded');status.textContent='';};image.onerror=function(){if(image.dataset.fallback==='0'){image.dataset.fallback='1';image.src='/japanese-training-lab/assets/manga/'+story.fallback+'/'+lang+'.jpg';return;}status.textContent='The manga could not be loaded. Please try again.';};image.src=firebase+lang+'.jpg?alt=media';root.querySelectorAll('[data-manga-language]').forEach(function(button){var active=button.dataset.mangaLanguage===lang;button.classList.toggle('active',active);button.setAttribute('aria-pressed',active?'true':'false');});updateStoryCopy();}
  function showReader(){reader.hidden=false;quiz.hidden=true;complete.hidden=true;progress.style.width=Math.round(index*100/questions.length)+'%';loadImage('ja');reader.scrollIntoView({behavior:'smooth',block:'start'});}
  function showQuiz(){reader.hidden=true;quiz.hidden=false;complete.hidden=true;renderQuestion();quiz.scrollIntoView({behavior:'smooth',block:'start'});}
  function renderQuestion(){locked=false;var item=questions[index];progress.style.width=Math.round(index*100/questions.length)+'%';root.querySelector('[data-question-count]').textContent='Question '+(index+1)+' of '+questions.length;root.querySelector('[data-question-number]').textContent=String(index+1).padStart(2,'0');root.querySelector('[data-question]').textContent=item.q;updateStoryCopy();var feedback=root.querySelector('[data-feedback]');feedback.textContent='';feedback.className='quiz-feedback';var choices=root.querySelector('[data-choices]');choices.innerHTML='';item.c.forEach(function(label,choiceIndex){var button=document.createElement('button');button.type='button';button.className='quiz-choice';button.textContent=label;button.addEventListener('click',function(){choose(choiceIndex);});choices.appendChild(button);});}
  function choose(selected){if(locked)return;locked=true;var item=questions[index],buttons=root.querySelectorAll('.quiz-choice'),correct=selected===item.a;buttons.forEach(function(button,buttonIndex){button.disabled=true;if(buttonIndex===item.a)button.classList.add('correct');});var feedback=root.querySelector('[data-feedback]');feedback.textContent=(correct?'Correct! ':'Not quite. ')+item.e;feedback.classList.add(correct?'good':'try');window.setTimeout(function(){if(!correct){renderQuestion();return;}if(index+1<questions.length){index++;save(index);if(index%2===0)showReader();else renderQuestion();return;}save(questions.length);quiz.hidden=true;complete.hidden=false;progress.style.width='100%';localStorage.setItem('japaneseLearning.n4Manga.collection.completed.v2','true');complete.scrollIntoView({behavior:'smooth',block:'start'});},1150);}
  root.querySelectorAll('[data-manga-language]').forEach(function(button){button.addEventListener('click',function(){loadImage(button.dataset.mangaLanguage);});});root.querySelector('[data-start-questions]').addEventListener('click',showQuiz);root.querySelector('[data-reread]').addEventListener('click',showReader);root.querySelector('[data-read-again]').addEventListener('click',function(){index=0;save(0);showReader();});
  loadImage('ja');if(directStory==='aka-manto')showReader();else if(params.get('resume')==='1'&&saved>0&&saved<questions.length){if(saved%2===0)showReader();else showQuiz();}else if(params.get('view')==='manga')showReader();
})();
